<div class="page-shell"><header class="page-header"><div><p class="eyebrow">ALUR KERJA</p><h1>Persetujuan<span>.</span></h1><p>Periksa dan tindak lanjuti dokumen sesuai kewenangan Anda.</p></div><div class="date-chip"><i class="ri-time-line"></i><?= count($approvals) ?> perlu tindakan</div></header><div class="approval-grid"><?php foreach($approvals as $a): ?><article class="approval-card"><div class="approval-top"><span class="priority <?= strtolower($a['priority']) ?>"><i class="ri-flashlight-line"></i><?= e($a['priority']) ?></span><small><?= e($a['sla']) ?> dalam antrean</small></div><span class="doc-type"><i class="ri-file-text-line"></i> DOKUMEN RESMI</span><h2><?= e($a['title']) ?></h2><p class="doc-number"><?= e($a['number']) ?></p><div class="approval-meta"><div><span class="avatar small"><?= strtoupper(substr($a['requester'],0,1)) ?></span><p><small>DIAJUKAN OLEH</small><strong><?= e($a['requester']) ?></strong><em><?= e($a['unit']) ?></em></p></div><div><small>TAHAP SAAT INI</small><strong><?= e($a['stage']) ?></strong><em><?= e($a['submitted']) ?></em></div></div><div class="approval-actions"><a class="secondary-button" href="?page=document-detail&id=<?= (int)Database::connection()->query('SELECT wi.document_id FROM workflow_steps ws JOIN workflow_instances wi ON wi.id=ws.workflow_instance_id WHERE ws.id='.(int)$a['id'])->fetchColumn() ?>"><i class="ri-eye-line"></i>Periksa</a><button class="approve-button" data-decision="approve" data-step="<?= (int)$a['id'] ?>"><i class="ri-check-line"></i>Setujui</button></div><div class="approval-actions"><button class="secondary-button" data-decision="revise" data-step="<?= (int)$a['id'] ?>">Minta revisi</button><button class="secondary-button" data-decision="reject" data-step="<?= (int)$a['id'] ?>">Tolak</button></div></article><?php endforeach; ?></div></div>
